export type CharacterId = keyof typeof animations;
export type PokoAnimationId = keyof typeof animations.poko;
export type LokoAnimationId = keyof typeof animations.loko;

export function getAnimation(
  character: CharacterId,
  animationId: string,
): AnimationDefinition | undefined {
  const characterAnimations = animations[character] as Record<string, AnimationDefinition>;
  return characterAnimations[animationId];
}